      font-size: 16px;
      padding: 14px 16px;
      border: 2px solid #e0e0e0;
      border-radius: 12px;
      background: #fff;
      cursor: pointer;
      transition: all 0.2s ease;
      display: flex;
      align-items: center;
      justify-content: space-between;
      color: #333;
    }

    .option-btn:hover {
      background: #f0f7ff;
      border-color: #4a90d9;
    }

    .option-btn.selected {
      background: #4a90d9;
      border-color: #4a90d9;
      color: #fff;
    }

    .option-btn .emoji {
      font-size: 20px;
      line-height: 1;
    }

    /* ===== BOTÃO AVANÇAR ===== */
    .next-btn {
      display: none;            /* aparece só após selecionar opção */
      margin-top: 24px;
      width: 100%;
      padding: 14px;
      font-family: 'Helvetica', Arial, sans-serif;
      font-weight: 700;
      font-size: 16px;
      color: #fff;
      background: #4a90d9;
      border: none;
      border-radius: 12px;
      cursor: pointer;
      transition: background 0.2s;
    }
    .next-btn:hover { background: #3a7bd6; }
    .next-btn:disabled { background: #b0b0b0; cursor: not-allowed; }

    /* ===== TELA FINAL (VSL + COMPRA) ===== */
    .final-step {
      text-align: center;
    }
    .video-container {
      margin: 24px auto;
      max-width: 480px;
      border-radius: 12px;
      overflow: hidden;
      box-shadow: 0 6px 20px rgba(0,0,0,0.1);
    }
    .video-container iframe {
      width: 100%;
      height: 260px;
      border: none;
    }
    .cta-btn {
      display: inline-block;
      margin-top: 28px;
      padding: 16px 40px;
      font-family: 'Helvetica', Arial, sans-serif;
      font-weight: 700;
      font-size: 18px;
      color: #fff;
      background: #2ecc71;
      border: none;
      border-radius: 14px;
      cursor: pointer;
      transition: transform 0.2s, background 0.2s;
      text-decoration: none;
    }
    .cta-btn:hover {
      transform: scale(1.03);
      background: #27ae60;
    }

    /* ===== PROGRESSO (opcional bonito) ===== */
    .progress-bar {
      width: 100%;
      height: 4px;
      background: #eee;
      border-radius: 2px;
      margin-bottom: 32px;
      overflow: hidden;
    }
    .progress-fill {
      height: 100%;
      background: linear-gradient(90deg, #4a90d9, #2ecc71);
      border-radius: 2px;
      transition: width 0.35s ease;
    }

    /* ===== RESPONSIVO ===== */
    @media (max-width: 480px) {
      .options-grid { grid-template-columns: 1fr; }
      .container { padding: 28px 20px; }
      .header h1 { font-size: 18px; }
    }
  </style>
</head>
<body>

  <div class="container">

    <!-- ======================= HEADER ======================= -->
    <div class="header">
      <!-- SUBSTITUA src pelo link da sua logo -->
      <img class="logo" src="logo.png" alt="Logo Louans">
      <h1>LOUANS</h1>
      <p class="subtitle">Descubra o que realmente importa para você.</p>
    </div>

    <!-- Barra de progresso -->
    <div class="progress-bar"><div class="progress-fill" id="progressFill"></div></div>

    <!-- ======================= ETAPA 1 ======================= -->
    <div class="step active" id="step1">
      <p class="question-text">Como você está se sentindo em relação ao seu corpo hoje?</p>
      <div class="options-grid">
        <button class="option-btn" data-answer="muito_contente">
          MUITO CONTENTE 😁
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="poderia_melhorar">
          PODERIA MELHORAR 😊
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="nada_contente">
          NADA CONTENTE 😑
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="muito_mal">
          MUITO MAL 😔
          <span class="emoji">🔗</span>
        </button>
      </div>
      <button class="next-btn" id="btnNext1" disabled>Continuar →</button>
    </div>

    <!-- ======================= ETAPA 2 ======================= -->
    <div class="step" id="step2">
      <p class="question-text">Qual é sua maior frustração atual?</p>
      <div class="options-grid">
        <button class="option-btn" data-answer="autoestima">
          Baixa autoestima 💔
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="comparacao">
          Comparação com outros 🫤
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="dietas">
          Dietas que nunca funcionam 🍽️
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="aceitacao">
          Acredito que não posso mudar 😕
          <span class="emoji">🔗</span>
        </button>
      </div>
      <button class="next-btn" id="btnNext2" disabled>Continuar →</button>
    </div>

    <!-- ======================= ETAPA 3 ======================= -->
    <div class="step" id="step3">
      <p class="question-text">O que mais te impede de ter mais confiança?</p>
      <div class="options-grid">
        <button class="option-btn" data-answer="inseguranca">
          Insegurança diária 😰
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="falta_resultados">
          Falta de resultados visíveis 👎
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="rotina">
          Rotina desgastante 😓
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="aceitacao_2">
          Medo do julgamento 👀
          <span class="emoji">🔗</span>
        </button>
      </div>
      <button class="next-btn" id="btnNext3" disabled>Continuar →</button>
    </div>

    <!-- ======================= ETAPA 4 ======================= -->
    <div class="step" id="step4">
      <p class="question-text">Se houvesse uma mudança mágica, qual seria?</p>
      <div class="options-grid">
        <button class="option-btn" data-answer="confianca">
          Sentir confiança em mim mesmo ✨
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="energia">
          Ter energia o dia todo ⚡
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="leveza">
          Me sentir leve e feliz 🌿
          <span class="emoji">🔗</span>
        </button>
        <button class="option-btn" data-answer="liberdade">
          Ser livre para ser quem sou 🦋
          <span class="emoji">🔗</span>
        </button>
      </div>
      <button class="next-btn" id="btnNext4" disabled>Ver minha solução →</button>
    </div>

    <!-- ======================= ETAPA FINAL (VSL + CTA) ======================= -->
    <div class="step final-step" id="stepFinal">
      <p style="font-family:'Helvetica',sans-serif;font-weight:700;font-size:22px;color:#1a1a1a;margin-bottom:8px;">
        Você está a um passo de transformar isso.
      </p>
      <p style="font-size:15px;color:#777;margin-bottom:20px;">
        Assista e descubra como recuperar sua confiança e viver com mais leveza.
      </p>

      <!-- COLA AQUI SEU VÍDEO (YouTube embed ou link direto). Exemplo YouTube: -->
      <!-- <iframe src="SEU_VIDEO_YOUTUBE_AQUI" title="VSL" loading="lazy"></iframe> -->
      <!-- Para vídeo próprio (Cloudflare, Vimeo, etc): -->
      <!-- <video controls loop muted style="max-width:480px;border-radius:12px;background:#000">
        <source src="SEU_VIDEO_MP4_AQUI" type="video/mp4">
        Seu navegador não suporta vídeo.
      </video> -->

      <a href="SEU_LINK_DE_COMPRA_AQUI" class="cta-btn" id="ctaBtn">
        QUERO ME TRANSFORMAR AGORA ➜
      </a>
      <p style="font-size:12px;color:#aaa;margin-top:18px;">
        Sua segurança é garantida. Cancelamento fácil em até 7 dias.
      </p>
    </div>

  </div>

  <!-- ======================= JAVASCRIPT ======================= -->
  <script>
    (function () {
      "use strict";

      // Estado global
      var respostas = [];
      const TOTAL_ETAPAS = 4;

      // Referências
      const steps = [
        document.getElementById('step1'),
        document.getElementById('step2'),
        document.getElementById('step3'),
        document.getElementById('step4'),
        document.getElementById('stepFinal')
      ];
      const botoesAvancar = [
        document.getElementById('btnNext1'),
        document.getElementById('btnNext2'),
        document.getElementById('btnNext3'),
        document.getElementById('btnNext4')
      ];

      function trocarEtapa(index) {
        steps.forEach((s, i) => s.classList.toggle('active', i === index));
        if (index < TOTAL_ETAPAS) {
          // Atualiza barra de progresso
          const pct = ((index + 1) / TOTAL_ETAPAS) * 100;
          document.getElementById('progressFill').style.width = pct + '%';
        }
        // Habilita botão avançar se houver resposta
        if (index < TOTAL_ETAPAS) {
          const btn = botoesAvancar[index];
          const todasSelecionadas = [...document.querySelectorAll('.option-btn')].every(b => b.classList.contains('selected'));
          btn.disabled = !todasSelecionadas;
        }
      }

      // Seleciona alternativa
      document.querySelectorAll('.option-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
          // Remove seleção anterior dentro do mesmo grid
          var grid = this.closest('.options-grid');
          grid.querySelectorAll('.option-btn').forEach(function (o) {
            o.classList.remove('selected');
          });
          this.classList.add('selected');
          respostas.push(this.getAttribute('data-answer'));
          trocarEtapa(respostas.length - 1);
        });
      });

      // Botão avançar
      botoesAvancar.forEach(function (btn, idx) {
        btn.addEventListener('click', function () {
          if (idx < TOTAL_ETAPAS - 1) {
            trocarEtapa(idx + 1);
          } else {
            // Chegou na etapa final
            document.querySelectorAll('.option-btn').forEach(function (o) {
              o.classList.remove('selected');
            });
            document.getElementById('ctaBtn').focus();
          }
        });
      });

      // CTA de compra (só redireciona)
      document.getElementById('ctaBtn').addEventListener('click', function (e) {
        e.preventDefault();
        window.location.href = "SEU_LINK_DE_COMPRA_AQUI";
      });

    })();
  </script>
