      const botoesAvancar = [
        document.getElementById('btnNext1'),
        document.getElementById('btnNext2'),
        document.getElementById('btnNext3'),
        document.getElementById('btnNext4')
      ];

      function trocarEtapa(index) {
        steps.forEach((s, i) => s.classList.toggle('active', i === index));
        if (index < TOTAL_ETAPAS) {
          // Atualiza barra de progresso
          const pct = ((index + 1) / TOTAL_ETAPAS) * 100;
          document.getElementById('progressFill').style.width = pct + '%';
        }
        // Habilita botão avançar se houver resposta
        if (index < TOTAL_ETAPAS) {
          const btn = botoesAvancar[index];
          const todasSelecionadas = [...document.querySelectorAll('.option-btn')].every(b => b.classList.contains('selected'));
          btn.disabled = !todasSelecionadas;
        }
      }

      // Seleciona alternativa
      document.querySelectorAll('.option-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
          // Remove seleção anterior dentro do mesmo grid
          var grid = this.closest('.options-grid');
          grid.querySelectorAll('.option-btn').forEach(function (o) {
            o.classList.remove('selected');
          });
          this.classList.add('selected');
          respostas.push(this.getAttribute('data-answer'));
          trocarEtapa(respostas.length - 1);
        });
      });

      // Botão avançar
      botoesAvancar.forEach(function (btn, idx) {
        btn.addEventListener('click', function () {
          if (idx < TOTAL_ETAPAS - 1) {
            trocarEtapa(idx + 1);
          } else {
            // Chegou na etapa final
            document.querySelectorAll('.option-btn').forEach(function (o) {
              o.classList.remove('selected');
            });
            document.getElementById('ctaBtn').focus();
          }
        });
      });

      // CTA de compra (só redireciona)
      document.getElementById('ctaBtn').addEventListener('click', function (e) {
        e.preventDefault();
        window.location.href = "SEU_LINK_DE_COMPRA_AQUI";
      });

    })();
  </script>
