<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
// ===================== FUNÇÕES DE CÁLCULO =====================

/**
 * Calcula a terceira incógnita da Lei de Ohm.
 * @param {object} vals - { V, I, R } com valores preenchidos ou null
 */
function calcularLeiOhm() {
    const v = parseFloat(document.getElementById('inV').value);
    const i = parseFloat(document.getElementById('inI').value);
    const r = parseFloat(document.getElementById('inR').value);

    const hasValue = (k) => k !== null && !isNaN(k) && k > 0;

    // Limpa resultados anteriores
    document.querySelectorAll('.result-box, .error-msg').forEach(el => el.style.display = 'none');

    let resultado = null;
    let err = '';

    if (!hasValue(v) && !hasValue(i) && !hasValue(r)) {
        err = '⚠ Preencha pelo menos duas variáveis para calcular a terceira.';
    } else if (hasValue(v) && hasValue(i)) {
        // V ? I ? → R = V / I
        try { resultado = v / i; } catch(e){ err = '⚠ Corrente zero causaria divisão nula.'; }
    } else if (hasValue(v) && hasValue(r)) {
        // V ? R ? → I = V / R
        try { resultado = v / r; } catch(e){ err = '⚠ Resistência zero causaria divisão nula.'; }
    } else if (hasValue(i) && hasValue(r)) {
        // I ? R ? → V = I × R
        try { resultado = i * r; } catch(e){ err = 'Valores inválidos.'; }
    } else {
        // Só um valor informado — tenta inferir qual é
        if (hasValue(v)) {
            if (hasValue(i)) resultado = v / r; else err = 'Informe também a Resistência ou Corrente.';
        } else if (hasValue(i)) {
            if (hasValue(r)) resultado = v * r; else err = 'Informe também a Tensão ou Resistência.';
        } else if (hasValue(r)) {
            if (hasValue(i)) resultado = v / i; else err = 'Informe também a Tensão ou Corrente.';
        }
    }

    if (err) {
        document.getElementById('errV').style.display = err.includes('Resistência') || err.includes('Corrente') ? '' : 'none';
        // Mostrar erro específico conforme mensagem
        const errEl = document.createElement('div');
        errEl.className = 'error-msg';
        errEl.innerHTML = err;
        errEl.id = 'erroGeral';
        document.querySelector('.calculadora-lei-ohm').appendChild(errEl);
        return;
    }

    if (resultado === Infinity || resultado === NaN) {
        err = '⚠ Valores incompatíveis para este cálculo.';
        const errEl = document.createElement('div');
        errEl.className = 'error-msg';
        errEl.innerHTML = err;
        document.querySelector('.calculadora-lei-ohm').appendChild(errEl);
        return;
    }

    // Formata números
    const fmt = (n) => {
        if (n < 0.1) return n.toFixed(4).replace(/0+$/, '');
        if (n >= 1000) return (n / 1000).toFixed(2).replace(/\.?0+$/, '') + ' k';
        return n.toFixed(2).replace(/\.?0+$/, '');
    };

    if (resultado < 1) resultado = fmt(resultado);
    else resultado = fmt(resultado);

    document.getElementById('valR').textContent = resultado;
    document.getElementById('outR').style.display = 'block';

    if (resultado === 'Inf' || resultado === 'NaN') resultado = '—';
    document.getElementById('valV').textContent = fmt(v);
    document.getElementById('outV').style.display = 'block';

    document.getElementById('valI').textContent = fmt(i);
    document.getElementById('outI').style.display = 'block';
}

/**
 * Cálculo de Potência Elétrica
 */
function calcularPotencia() {
    const v = parseFloat(document.getElementById('pv').value);
    const i = parseFloat(document.getElementById('pi').value);

    const limpo = (el) => {
        const res = document.getElementById('resPotencia');
        res.style.display = 'none';
        document.querySelectorAll('#resPotencia span').forEach(s => s.textContent = '');
        el.querySelectorAll('small').forEach(s => s.textContent = '');
        // remove classes extras
    };

    limpo(document.getElementById('resPotencia'));

    if (!v || !i) {
        const err = document.createElement('div');
        err.className = 'error-msg';
        err.innerHTML = '⚠ Preencha Tensão (V) e Corrente (A) para calcular a potência.';
        document.getElementById('potencia').insertBefore(err, document.querySelector('.mb-5'));
        return;
    }

    const P_vi = v * i;
    const R = parseFloat(document.getElementById('inR').value);
    const P_Ri = R ? R * Math.pow(i, 2) : null;
    const P_VR = (v * v) / (R > 0 ? R : 1) ;

    const resBox = document.getElementById('resPotencia');
    resBox.style.display = 'block';

    document.getElementById('valP').textContent = 
        `P = ${fmt(P_vi)} W<br><small>(também: P = R·I² = ${P_Ri ? fmt(P_Ri) : '—'} W &nbsp;|&nbsp; P = V²/R = ${P_VR.toFixed(2)} W)</small>`;
}

// ===================== EVENTOS =====================

document.addEventListener('DOMContentLoaded', () => {
    // Botão "Calcular" da Lei de Ohm — dispara ao clicar em qualquer input
    const inputsLH = ['inV','inI','inR'];
    inputsLH.forEach(id => {
        const inp = document.getElementById(id);
        if (inp) {
            inp.addEventListener('blur', calcularLeiOhm);
            inp.addEventListener('change', () => {
                // Se só um campo mudou e outro já tinha valor, recalcula
                calcularLeiOhm();
            });
        }
    });

    // Recálculo automático se todos os campos vazios → nada mostra
    ['inV','inI','inR'].forEach(id => {
        document.getElementById(id).addEventListener('input', () => calcularLeiOhm());
    });

    // Foco suave nos inputs
    document.querySelectorAll('.form-control').forEach(el => {
        el.addEventListener('focus', () => el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    });
});
</script>
</body>
